// Dos triggers posibles (GET de verificación / POST de eventos): Config ya mezcló
// sus campos hacia aquí (includeOtherFields), así que basta con $json.
const cfg = $json;
const q = cfg.query || {};
const headers = cfg.headers || {};

// --- 1) Verificación del webhook (GET de Meta) ---
if (q['hub.mode'] || q['hub.challenge']) {
  const ok = q['hub.verify_token'] === cfg.verify_token;
  return [{ json: { tipo: ok ? 'verificacion' : 'ignorar',
    challenge: ok ? String(q['hub.challenge'] ?? '') : '',
    motivo: ok ? null : 'verify_token no coincide' } }];
}

// --- 2) Cuerpo ---
// Meta firma los BYTES EXACTOS que envía, así que re-serializar el JSON ya
// parseado no sirve: un espacio de diferencia y el HMAC no cuadra. O tenemos el
// crudo o la firma no se puede comprobar, y punto.
//
// `rawBody: true` lo entrega de formas distintas según la versión de n8n
// (string, Buffer serializado, binario aparte). Se aceptan todas y se anota
// CUÁL apareció: así, si algún día deja de cuadrar, el dato está a la vista en
// vez de haber que deducirlo.
let raw = null, body = null, forma_cuerpo = 'ausente';

// De dónde se saca el cuerpo: del WEBHOOK, no de $json. $json es lo que dejó el
// nodo `Config`, que es un Set -- y un Set puede descartar la parte binaria, que
// es justo donde `rawBody` deja los bytes. Leyéndolo del origen ese eslabón
// desaparece. Si el nodo no corrió (llegó por el trigger GET), se cae al $json
// de siempre.
let b = cfg.body;
let origen_cuerpo = 'config';
try {
  const hook = $('Webhook · WhatsApp (POST)').first();
  if (hook) {
    origen_cuerpo = 'webhook';
    if (hook.json && hook.json.body !== undefined) b = hook.json.body;
    const bin = hook.binary || {};
    const dato = bin.data || bin.body || Object.values(bin)[0];
    // El binario manda: si existe, son los bytes tal cual llegaron.
    if (dato && dato.data) {
      try {
        raw = (typeof Buffer !== 'undefined')
          ? Buffer.from(dato.data, 'base64').toString('utf8')
          : new TextDecoder().decode(Uint8Array.from(atob(dato.data), ch => ch.charCodeAt(0)));
        forma_cuerpo = 'binario_webhook';
      } catch (e) { /* seguimos con b */ }
    }
  }
} catch (e) { /* el POST no corrió en esta ejecución */ }

if (raw) {
  // ya resuelto desde el binario del webhook
} else if (typeof b === 'string') {
  forma_cuerpo = 'string';
  raw = b;
} else if (b && typeof b === 'object' && b.type === 'Buffer' && Array.isArray(b.data)) {
  forma_cuerpo = 'buffer_json';
  try { raw = Buffer.from(b.data).toString('utf8'); } catch (e) { raw = null; }
} else if (typeof Buffer !== 'undefined' && Buffer.isBuffer && Buffer.isBuffer(b)) {
  forma_cuerpo = 'buffer';
  try { raw = b.toString('utf8'); } catch (e) { raw = null; }
} else if (b && typeof b === 'object') {
  // Ya viene parseado: el crudo se perdió por el camino y no hay firma posible.
  forma_cuerpo = 'objeto_parseado';
  body = b;
}

// n8n puede dejar el cuerpo en la parte binaria en lugar de en $json.
if (!raw && !body) {
  try {
    const bin = $input.first().binary || {};
    const dato = bin.data || bin.body || Object.values(bin)[0];
    if (dato && dato.data) {
      forma_cuerpo = 'binario';
      raw = Buffer.from(dato.data, 'base64').toString('utf8');
    }
  } catch (e) { /* no hay binario */ }
}

if (raw && !body) { try { body = JSON.parse(raw); } catch (e) { body = null; } }
if (!body) return [{ json: { tipo: 'ignorar', motivo: 'cuerpo no parseable', forma_cuerpo, origen_cuerpo } }];

// --- 3) Firma X-Hub-Signature-256 ---
// `no_comprobada` a secas no decía POR QUÉ, y esa ambigüedad ya nos costó una
// prueba en falso: el App Secret era correcto y el problema era el cuerpo.
let firma = 'no_comprobada';
let firma_motivo = null;
const sigHeader = headers['x-hub-signature-256'] || headers['X-Hub-Signature-256'] || '';

if (!cfg.app_secret || String(cfg.app_secret).startsWith('REPLACE_')) {
  firma_motivo = 'falta app_secret en Config';
} else if (!sigHeader) {
  firma_motivo = 'la petición no trae cabecera x-hub-signature-256';
} else if (!raw) {
  firma_motivo = 'sin cuerpo crudo (llegó como ' + forma_cuerpo + '); revisa rawBody en el webhook';
} else {
  // HMAC-SHA256 en JS puro. No es por gusto: el task runner de n8n prohíbe
  // require('crypto') ("Module 'crypto' is disallowed") Y no expone Web Crypto
  // (comprobado: globalThis.crypto es undefined). Sin esto no hay forma de
  // validar la firma de Meta desde un Code node.
  //
  // Por qué es asumible aquí: un error de implementación produce 'invalida',
  // nunca un 'valida' falso -- para colar una firma habría que coincidir por
  // casualidad con el HMAC de Meta. Falla cerrado y ruidoso.
  //
  // Verificado contra los 6 vectores oficiales del RFC 4231, las 301 longitudes
  // de 0 a 300 bytes y 500 pares clave/mensaje aleatorios, todo contra
  // node:crypto. El bug que tuvo durante diez minutos estaba justo en la
  // frontera que el relleno hace especial (len+9 múltiplo de 64), y por eso se
  // prueban todas las longitudes y no una muestra.
  const K = [
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];

  function sha256(bytes) {
    const h = [0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
    const len = bytes.length;
    const bitLenHi = Math.floor(len / 0x20000000);
    const bitLenLo = (len << 3) >>> 0;
    // El relleno lleva 1 byte 0x80 + 8 de longitud: el total es el menor múltiplo
    // de 64 que da cabida a len+9. Ojo cuando len+9 es EXACTAMENTE múltiplo de 64
    // (len = 55, 119, 183...): ahí no hace falta bloque extra, y una fórmula que
    // lo añade da un digest distinto solo en esos casos.
    const total = Math.ceil((len + 9) / 64) * 64;
    const m = new Uint8Array(total);
    m.set(bytes); m[len] = 0x80;
    const dv = new DataView(m.buffer);
    dv.setUint32(total - 8, bitLenHi);
    dv.setUint32(total - 4, bitLenLo);

    const w = new Uint32Array(64);
    const rotr = (x, n) => (x >>> n) | (x << (32 - n));
    for (let off = 0; off < total; off += 64) {
      for (let i = 0; i < 16; i++) w[i] = dv.getUint32(off + i * 4);
      for (let i = 16; i < 64; i++) {
        const s0 = rotr(w[i-15],7) ^ rotr(w[i-15],18) ^ (w[i-15] >>> 3);
        const s1 = rotr(w[i-2],17) ^ rotr(w[i-2],19) ^ (w[i-2] >>> 10);
        w[i] = (w[i-16] + s0 + w[i-7] + s1) >>> 0;
      }
      let [a,b,c,d,e,f,g,hh] = h;
      for (let i = 0; i < 64; i++) {
        const S1 = rotr(e,6) ^ rotr(e,11) ^ rotr(e,25);
        const ch = (e & f) ^ (~e & g);
        const t1 = (hh + S1 + ch + K[i] + w[i]) >>> 0;
        const S0 = rotr(a,2) ^ rotr(a,13) ^ rotr(a,22);
        const maj = (a & b) ^ (a & c) ^ (b & c);
        const t2 = (S0 + maj) >>> 0;
        hh=g; g=f; f=e; e=(d+t1)>>>0; d=c; c=b; b=a; a=(t1+t2)>>>0;
      }
      h[0]=(h[0]+a)>>>0; h[1]=(h[1]+b)>>>0; h[2]=(h[2]+c)>>>0; h[3]=(h[3]+d)>>>0;
      h[4]=(h[4]+e)>>>0; h[5]=(h[5]+f)>>>0; h[6]=(h[6]+g)>>>0; h[7]=(h[7]+hh)>>>0;
    }
    const out = new Uint8Array(32);
    for (let i = 0; i < 8; i++) new DataView(out.buffer).setUint32(i*4, h[i]);
    return out;
  }

  function hmacSha256(keyBytes, msgBytes) {
    let k = keyBytes;
    if (k.length > 64) k = sha256(k);
    const pad = new Uint8Array(64); pad.set(k);
    const ipad = new Uint8Array(64), opad = new Uint8Array(64);
    for (let i = 0; i < 64; i++) { ipad[i] = pad[i] ^ 0x36; opad[i] = pad[i] ^ 0x5c; }
    const inner = new Uint8Array(64 + msgBytes.length);
    inner.set(ipad); inner.set(msgBytes, 64);
    const ih = sha256(inner);
    const outer = new Uint8Array(96);
    outer.set(opad); outer.set(ih, 64);
    return sha256(outer);
  }

  const hex = (b) => [...b].map(x => x.toString(16).padStart(2,'0')).join('');

  const aBytes = (s) => {
    if (typeof TextEncoder !== 'undefined') return new TextEncoder().encode(s);
    return new Uint8Array(Buffer.from(s, 'utf8'));
  };

  const esperado = 'sha256=' + hex(hmacSha256(aBytes(cfg.app_secret), aBytes(raw)));

  // Comparación en tiempo constante: comparar firmas con === filtra por dónde
  // dejan de coincidir. Aquí el riesgo es remoto, pero son cuatro líneas.
  let dif = esperado.length ^ sigHeader.length;
  for (let i = 0; i < esperado.length && i < sigHeader.length; i++) {
    dif |= esperado.charCodeAt(i) ^ sigHeader.charCodeAt(i);
  }
  firma = dif === 0 ? 'valida' : 'invalida';
  if (firma === 'invalida') firma_motivo = 'el HMAC no coincide: ¿app_secret equivocado?';
}
// El veredicto viaja en la SALIDA del nodo, no solo en un console.log: los Code
// nodes corren en un task runner aparte y su log puede no llegar a `docker logs`,
// así que la firma era invisible por los dos caminos. Ahora se ve en la ejecución.
console.log('[whatsapp] firma=' + firma + (firma_motivo ? ' (' + firma_motivo + ')' : ''));
if (cfg.require_signature === true && firma !== 'valida') {
  return [{ json: { tipo: 'ignorar', motivo: 'firma ' + firma, firma, firma_motivo, forma_cuerpo, origen_cuerpo } }];
}

// --- 4) Normalizar el payload de Meta ---
const value = body?.entry?.[0]?.changes?.[0]?.value || {};
const msg = value?.messages?.[0];
// Los avisos de estado (sent/delivered/read) llegan al mismo webhook: se ignoran.
if (!msg) return [{ json: { tipo: 'ignorar', motivo: value.statuses ? 'status' : 'sin mensajes', firma, firma_motivo, forma_cuerpo, origen_cuerpo } }];

const pnid = value?.metadata?.phone_number_id || null;
if (pnid && cfg.phone_number_id && !String(cfg.phone_number_id).startsWith('REPLACE_')
    && pnid !== cfg.phone_number_id) {
  return [{ json: { tipo: 'ignorar', motivo: 'phone_number_id ajeno: ' + pnid, firma, firma_motivo, forma_cuerpo, origen_cuerpo } }];
}

const from = msg.from || null;                       // E.164 sin '+'
const perfil = value?.contacts?.[0]?.profile?.name || null;
const texto = msg.type === 'text' ? (msg.text?.body || '') : '';

return [{ json: {
  tipo: msg.type === 'text' ? 'mensaje' : 'no_texto',
  firma, firma_motivo, forma_cuerpo, origen_cuerpo,
  wamid: msg.id || null,
  from,
  entry: {
    canal: 'whatsapp',
    session_key: 'whatsapp:' + from,
    message: texto,
    from: { phone: from ? '+' + from : null, name: perfil },
    tenant: cfg.tenant || '__TENANT_ID__',
    reply_to: { phone_number_id: cfg.phone_number_id },
    client_message_id: msg.id || null,
  },
} }];

const e = $json ?? {};
const cfg = $('Config (editar por tenant)').item.json;
const norm = $('Code · Clasificar y normalizar').item.json;
const base_url = `https://graph.facebook.com/${cfg.graph_version || 'v21.0'}/${cfg.phone_number_id}/messages`;
const items = [];

// WhatsApp NO entiende markdown estándar: su negrita es *así* (un asterisco), la cursiva
// _así_ y el tachado ~así~. Un **negrita** del agente se ve con los asteriscos puestos, y
// las cabeceras ## salen tal cual. Se normaliza aquí, en el adapter, porque cada canal
// tiene su dialecto: el Core produce UN texto y cada canal lo adapta a lo suyo.
const aWhatsApp = (t) => (t || '').toString()
  .replace(/`{3}([\s\S]*?)`{3}/g, '$1')            // bloques de código: fuera
  .replace(/^#{1,6}\s*(.+)$/gm, '*$1*')            // ## Título  -> *Título*
  .replace(/\*\*\*(.+?)\*\*\*/g, '*$1*')           // ***x***    -> *x*
  .replace(/\*\*(.+?)\*\*/g, '*$1*')               // **x**      -> *x*
  .replace(/__(.+?)__/g, '_$1_')                   // __x__      -> _x_
  .replace(/`(.+?)`/g, '$1')                       // `x`        -> x
  .replace(/\[([^\]]+)\]\((https?:\/\/[^)\s]+)\)/g, '$1: $2')  // [texto](url) -> texto: url
  .replace(/^[ \t]*[*+][ \t]+/gm, '- ')            // viñetas * o + -> -
  .trim();

// Aviso de privacidad como botón CTA-URL: WhatsApp no permite enlaces con texto
// personalizado en un mensaje de texto normal, así que va como mensaje interactivo
// aparte (tocar el botón solo abre la URL, no genera respuesta que haya que procesar).
// Límite real de WhatsApp: display_text del botón <= 20 caracteres.
if (e.privacy_prompt && e.privacy_prompt.url) {
  items.push({ json: {
    _url: base_url,
    _body: {
      messaging_product: 'whatsapp', recipient_type: 'individual', to: norm.from,
      type: 'interactive',
      interactive: {
        type: 'cta_url',
        body: { text: (e.privacy_prompt.intro || '').slice(0, 1024) },
        action: {
          name: 'cta_url',
          parameters: {
            display_text: (e.privacy_prompt.label || 'Ver política').slice(0, 20),
            url: e.privacy_prompt.url,
          },
        },
      },
    },
  } });
}

// El resto de la respuesta (si lo hay) va como texto normal, sin repetir el aviso.
const texto = aWhatsApp(e.core_reply ?? e.reply ?? '');
if (texto) {
  items.push({ json: {
    _url: base_url,
    _body: { messaging_product: 'whatsapp', recipient_type: 'individual', to: norm.from,
             type: 'text', text: { preview_url: false, body: texto } },
  } });
}

return items;

// Puede haber 1 o 2 respuestas (botón de privacidad + texto): se comprueban todas,
// no solo la primera, para no perder un fallo en el segundo envío.
const items = $input.all();
return items.map(item => {
  const r = item.json ?? {};
  const code = r.statusCode ?? 0;
  const body = (r.body ?? r) || {};
  if (code >= 300 || body.error) {
    throw new Error('WhatsApp send devolvió ' + code + ': ' + JSON.stringify(body.error || body));
  }
  return { json: { enviado: true, wamid: (body.messages && body.messages[0] && body.messages[0].id) || null } };
});

const cfg = $('Config (editar por tenant)').item.json;
const norm = $json ?? {};
return [{ json: {
  _url: `https://graph.facebook.com/${cfg.graph_version || 'v21.0'}/${cfg.phone_number_id}/messages`,
  _body: { messaging_product: 'whatsapp', recipient_type: 'individual',
           to: norm.from, type: 'text',
           text: { preview_url: false,
                   body: 'De momento solo puedo leer mensajes de texto. ¿Me lo escribes?' } },
} }];
